    "mnemonic": "Slope of adiabatic PV curve is steeper than isothermal: $\\left(\\frac{dP}{dV}\\right)_{\\text{ad}} = \\gamma\\left(\\frac{dP}{dV}\\right)_{\\text{iso}}$.",
